It seems that now all the Scalar is always replaced with ""(empty string) instead of "null". 

See below:
```
$ cat 1290.yaml
thisIsEmpty:
thisIsnull: null
thisIsNull: Null
thisIsNULL: NULL
thisIsStr: "null"
$ cat 1290.cpp
#include <iostream>
#include <cstdio>
#include <string>
#include <yaml-cpp/yaml.h>

int main() {
    std::string input;
    char c;
    while((c = getchar()) != EOF) input += c;

    YAML::Node node = YAML::Load(input);
    for(auto it = node.begin(); it != node.end(); ++it) {
        std::cout << it->first << ": " << it->second.as<std::string>()
                  << ", Scalar: \"" << it->second.Scalar() << "\"" << '\n';
    }
    return 0;
}
$ g++ 1290.cpp -o1290 -lyaml-cpp && ./1290 < 1290.yaml
thisIsEmpty: null, Scalar: ""
thisIsnull: null, Scalar: ""
thisIsNull: null, Scalar: ""
thisIsNULL: null, Scalar: ""
thisIsStr: null, Scalar: "null"
```
